  /* Pie: solo una línea y el número de página al centro */
  .pie {
    position: fixed;
    bottom: -18mm; left: 0; right: 0;
    height: 10mm;
    border-top: 1px solid #000000;
    text-align: center;
    padding-top: 3mm;
    font-size: 10pt;
  }
  .pie .num:after { content: counter(page); }

