  .meta { margin: 0 0 4mm; font-size: 10pt; color: #4a4a4a; }
  .meta b { color: #000000; }

  /* Bloques de contraseñas */
  .entrada {
    margin-top: 5mm;
    padding: 4mm 5mm 4mm 6mm;
