  }
  .entrada h2 { margin: 0 0 2mm; font-size: 14pt; }
  .fila { margin: 0; }
  .etq { display: inline-block; width: 38mm; font-weight: bold; color: #0a6b3b; }
  .val { display: inline-block; width: 100mm; word-wrap: break-word; }
  .clave { font-family: "DejaVu Sans Mono", "Courier New", monospace; font-weight: bold; }

